"""Regression tests for the Toto-2 forecaster."""

import numpy as np
import pandas as pd
import pytest
from skbase.utils.dependencies import _check_estimator_deps

from sktime.datasets import load_airline
from sktime.forecasting.toto2 import Toto2Forecaster

# Reference forecasts were generated by calling toto2.Toto2Model.forecast()
# directly (toto-2==2.0.0), bypassing sktime entirely.
_TOTO2_AIRLINE_REFERENCE_CASES = [
    pytest.param(
        128,
        16,
        None,
        [447.98572, 429.6945, 483.45844],
        id="context-128-patch-aligned",
    ),
    pytest.param(
        100,
        16,
        None,
        [455.59778, 433.8418, 489.8762],
        id="context-100-needs-left-padding",
    ),
    pytest.param(
        128,
        64,
        32,
        [447.98572, 429.6945, 483.45844],
        id="decode-block-size-32",
    ),
]


@pytest.mark.skipif(
    not _check_estimator_deps(Toto2Forecaster, severity="none"),
    reason="run test only if Toto2Forecaster soft dependencies are present",
)
@pytest.mark.parametrize(
    "context_len,horizon,decode_block_size,expected_head",
    _TOTO2_AIRLINE_REFERENCE_CASES,
)
def test_toto2_airline_predictions_match_source_reference(
    context_len, horizon, decode_block_size, expected_head
):
    """Toto-2 predictions match the original Toto2Model.forecast() outputs."""
    y = load_airline()
    y_train = y.iloc[-context_len:]
    fh = np.arange(1, horizon + 1)
    forecaster = Toto2Forecaster(
        model_path="Datadog/Toto-2.0-4m",
        device="cpu",
        decode_block_size=decode_block_size,
        seed=0,
    )

    y_pred = forecaster.fit(y_train, fh=fh).predict(fh=fh)

    np.testing.assert_allclose(
        y_pred.iloc[:3].to_numpy().flatten(),
        np.asarray(expected_head, dtype=np.float32),
        rtol=1e-5,
        atol=1e-4,
    )


@pytest.mark.skipif(
    not _check_estimator_deps(Toto2Forecaster, severity="none"),
    reason="run test only if Toto2Forecaster soft dependencies are present",
)
def test_toto2_multivariate_predictions_match_source_reference():
    """Toto-2 multivariate predictions match Toto2Model.forecast() outputs."""
    rng = np.random.default_rng(0)
    n_vars, context_len, horizon = 3, 100, 12
    values = rng.standard_normal((n_vars, context_len)).astype(np.float32)
    y = pd.DataFrame(values.T, columns=["a", "b", "c"])
    fh = np.arange(1, horizon + 1)
    forecaster = Toto2Forecaster(
        model_path="Datadog/Toto-2.0-4m",
        device="cpu",
        seed=0,
    )

    y_pred = forecaster.fit(y, fh=fh).predict(fh=fh)

    expected_head = np.asarray(
        [
            [-0.4244963, 0.20141384, -0.12772694],
            [0.01275067, -0.01122135, -0.05671813],
            [-0.07579251, -0.15499641, -0.2406247],
        ],
        dtype=np.float32,
    )
    np.testing.assert_allclose(
        y_pred.iloc[:3].to_numpy().T,
        expected_head,
        rtol=1e-5,
        atol=1e-4,
    )
